public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            return 0; // null string cannot contain any substring
        }
        minLen = Math.min(minLen, s.length());
        if (s.isEmpty()) {
            return 0; // one empty string => no common substring
        }
    }
    String first = strings.get(0);
    for (int len = minLen; len >= 1; len--) {
        Set<String> substrings = new HashSet<>();
        for (int i = 0; i + len <= first.length(); i++) {
            substrings.add(first.substring(i, i + len));
        }
        ListIterator<String> it = strings.listIterator(1);
        while (!substrings.isEmpty() && it.hasNext()) {
            String curr = it.next();
            Set<String> remaining = new HashSet<>();
            for (String sub : substrings) {
                String rev = new StringBuilder(sub).reverse().toString();
                if (curr.contains(sub) || curr.contains(rev)) {
                    remaining.add(sub);
                }
            }
            substrings = remaining;
        }
        if (!substrings.isEmpty()) {
            return len;
        }
    }
    return 0;
}

