public static int maxRegions(int N) {
    if (N < 1) {
        throw new IllegalArgumentException("Number of triangles must be at least 1");
    }
    // Compute 3*N^2 - 3*N + 2 using long to avoid overflow for large N,
    // then cast back to int if within range.
    long result = 3L * N * N - 3L * N + 2L;
    if (result > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result too large for int");
    }
    return (int) result;
}

