public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Basic validation
    try {
        if (n <= 0 || start == null || end == null || start.length != n || end.length != n) {
            return "cannot be travelled";
        }
        if (paths == null) {
            return "cannot be travelled";
        }

        String startKey = coordKey(start);
        String endKey = coordKey(end);
        if (startKey.equals(endKey)) {
            return "can be travelled";
        }

        // Build adjacency list
        java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
        for (int[] path : paths) {
            if (path == null || path.length != 2 * n) {
                // Invalid path entry; skip or break
                return "cannot be travelled";
            }
            int[] a = java.util.Arrays.copyOfRange(path, 0, n);
            int[] b = java.util.Arrays.copyOfRange(path, n, 2 * n);
            String aKey = coordKey(a);
            String bKey = coordKey(b);
            graph.computeIfAbsent(aKey, k -> new java.util.ArrayList<>()).add(bKey);
            graph.computeIfAbsent(bKey, k -> new java.util.ArrayList<>()).add(aKey);
        }

        // BFS
        java.util.Queue<String> queue = new java.util.LinkedList<>();
        java.util.Set<String> visited = new java.util.HashSet<>();
        queue.offer(startKey);
        visited.add(startKey);

        while (!queue.isEmpty()) {
            String current = queue.poll();
            java.util.List<String> neighbors = graph.getOrDefault(current, java.util.Collections.emptyList());
            for (String neighbor : neighbors) {
                if (neighbor.equals(endKey)) {
                    return "can be travelled";
                }
                if (!visited.contains(neighbor)) {
                    visited.add(neighbor);
                    queue.offer(neighbor);
                }
            }
        }
        // If BFS completes without finding end
        return "cannot be travelled";
    } catch (Exception e) {
        // Any unexpected exception results in negative answer
        return "cannot be travelled";
    }
}

private static String coordKey(int[] coord) {
    if (coord == null) return "";
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < coord.length; i++) {
        sb.append(coord[i]);
        if (i < coord.length - 1) sb.append(",");
    }
    return sb.toString();
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate input sizes
    if (n <= 0 || start == null || end == null || start.length != n || end.length != n) {
        return "cannot be travelled";
    }

    // Helper to convert coordinate array to a unique string key
    java.util.function.Function<int[], String> coordKey = coord -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            sb.append(coord[i]);
            if (i < coord.length - 1) sb.append(',');
        }
        return sb.toString();
    };

    String startKey = coordKey.apply(start);
    String endKey = coordKey.apply(end);

    // If start equals end, travel is trivially possible
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // Build adjacency map from paths
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();

    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length != 2 * n) {
                // Skip malformed path entries
                continue;
            }
            int[] a = new int[n];
            int[] b = new int[n];
            System.arraycopy(path, 0, a, 0, n);
            System.arraycopy(path, n, b, 0, n);
            String keyA = coordKey.apply(a);
            String keyB = coordKey.apply(b);
            // Ensure both nodes exist in adjacency map
            adj.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
            adj.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
        }
    }

    // BFS to find a path from start to end
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = adj.get(current);
        if (neighbors == null) {
            continue;
        }
        for (String neighbor : neighbors) {
            if (neighbor.equals(endKey)) {
                return "can be travelled";
            }
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        throw new IllegalArgumentException("Input date string cannot be null");
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        throw new IllegalArgumentException("Expected format \"MM dd yyyy\"");
    }
    int month, day, year;
    try {
        month = Integer.parseInt(parts[0]);
        day   = Integer.parseInt(parts[1]);
        year  = Integer.parseInt(parts[2]);
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Month, day, and year must be numeric");
    }

    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Month must be between 01 and 12");
    }

    // Create calendar and validate the date
    java.util.GregorianCalendar cal = new java.util.GregorianCalendar(year, month - 1, day);
    // GregorianCalendar will roll over if the supplied day is invalid; adjust check below
    if (cal.get(java.util.Calendar.MONTH) != month - 1 ||
        cal.get(java.util.Calendar.DAY_OF_MONTH) != day ||
        cal.get(java.util.Calendar.YEAR) != year) {
        throw new IllegalArgumentException("Invalid date");
    }

    String monthName = new java.text.DateFormatSymbols().getMonths()[month - 1];
    String weekDayName = new java.text.DateFormatSymbols().getWeekdays()[cal.get(java.util.Calendar.DAY_OF_WEEK)];

    return String.format("%s %d, %d is a %s", monthName, day, year, weekDayName);
}

