public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int trim = (int)Math.floor(n * 0.05);
    java.util.Arrays.sort(arr);
    int start = trim;
    int end = n - trim; // exclusive
    if (end <= start) {
        return 0.0;
    }
    double sum = 0.0;
    for (int i = start; i < end; i++) {
        sum += arr[i];
    }
    return sum / (end - start);
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Array must contain at least one element.");
    }
    int n = arr.length;
    int k = n / 20; // number of elements to remove from each side (5% of n)
    java.util.Arrays.sort(arr);
    long sum = 0;
    for (int i = k; i < n - k; i++) {
        sum += arr[i];
    }
    int count = n - 2 * k;
    return (double) sum / count;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Input array cannot be null or empty");
    }
    int n = arr.length;
    int k = n / 20; // number of elements to trim from each side
    if (k == 0) { // if array too small for 5% trimming, return mean of all elements
        long total = 0;
        for (int v : arr) {
            total += v;
        }
        return ((double) total) / n;
    }
    java.util.Arrays.sort(arr);
    long sum = 0;
    for (int i = k; i < n - k; i++) {
        sum += arr[i];
    }
    int remaining = n - 2 * k;
    if (remaining <= 0) {
        throw new IllegalArgumentException("Array too small after trimming");
    }
    return ((double) sum) / remaining;
}

