    long sum = 0;
    for (int i = remove; i < n - remove; i++) {
        sum += arr[i];
    }
    int remaining = n - 2 * remove;
    return sum / (double) remaining;
}

public boolean canArrange(int[] arr, int k) {
    // Basic validation: array must be non-null, have even length, and divisor must be positive
    if (arr == null || (arr.length & 1) == 1 || k <= 0) {
        return false;
    }

    // Count frequency of each remainder when divided by k
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = num % k;
        if (rem < 0) {
            rem += k; // make remainder positive
        }
        freq[rem]++;
    }

    // Remainder 0 elements must be pairable among themselves
    if (freq[0] % 2 != 0) {
        return false;
    }

    // For each remainder i (1 <= i <= k/2), its complement (k - i) must have the same count
    // Handle the special case when k is even: remainder k/2 must be pairable among itself
    int limit = k / 2;
    for (int i = 1; i <= limit; i++) {
        int complement = k - i;
        if (i == complement) {
            // This happens only when k is even and i == k/2
            if (freq[i] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[i] != freq[complement]) {
                return false;
            }
        }
    }

    return true;
}

