    int upperLimit = k / 2;
    // When k is even, we already handled remainder k/2, so loop up to upperLimit-1
    int limit = (k % 2 == 0) ? upperLimit - 1 : upperLimit;
    for (int r = 1; r <= limit; r++) {
        int complement = k - r;
        if (remainderCount[r] != remainderCount[complement]) {
            return false;
        }
    }

    return true;
