    if (s == null || s.isEmpty()) {
        return "";
    }
    java.util.TreeMap<Character, Integer> freq = new java.util.TreeMap<>();
    for (char ch : s.toCharArray()) {
        freq.merge(ch, 1, Integer::sum);
    }

    StringBuilder result = new StringBuilder();
    while (!freq.isEmpty()) {
        // Ascending part
        java.util.Map.Entry<Character, Integer> entry = freq.firstEntry();
        char cur = entry.getKey();
        result.append(cur);
        if (entry.getValue() == 1) {
            freq.remove(cur);
        } else {
            freq.put(cur, entry.getValue() - 1);
        }

        java.util.Map.Entry<Character, Integer> next;
        while ((next = freq.higherEntry(cur)) != null) {
            cur = next.getKey();
            result.append(cur);
            if (next.getValue() == 1) {
                freq.remove(cur);
            } else {
                freq.put(cur, next.getValue() - 1);
            }
        }

        // Descending part
        if (freq.isEmpty()) {
            break;
        }
        entry = freq.lastEntry();
        cur = entry.getKey();
        result.append(cur);
        if (entry.getValue() == 1) {
            freq.remove(cur);
        } else {
            freq.put(cur, entry.getValue() - 1);
        }

        java.util.Map.Entry<Character, Integer> prev;
        while ((prev = freq.lowerEntry(cur)) != null) {
            cur = prev.getKey();
            result.append(cur);
            if (prev.getValue() == 1) {
                freq.remove(cur);
            } else {
                freq.put(cur, prev.getValue() - 1);
            }
        }
    }
    return result.toString();
}

public String sortString(String s) {
    if (s == null) {
        return null;
    }
    int[] freq = new int[65536];
    for (int i=0; i<s.length(); i++) {
        char c = s.charAt(i);
        freq[c]++;
    }
    StringBuilder sb = new StringBuilder(s.length());
    int remaining = s.length();
    while (remaining > 0) {
        // ascending
        for (int i=0; i<freq.length && remaining>0; i++) {
            if (freq[i] > 0) {
                sb.append((char)i);
                freq[i]--;
                remaining--;
            }
        }
        // descending
        for (int i=freq.length-1; i>=0 && remaining>0; i--) {
            if (freq[i] > 0) {
                sb.append((char)i);
