        if (lastPickedDown == -1) break; // no chars left
        // now pick smaller ones
        for (int i=lastPickedDown-1; i>=0; i--) {
            if (freq[i] > 0) {
                sb.append((char)i);
                freq[i]--;
                total--;
                lastPickedDown = i;
            }
        }
    }
    return sb.toString();
}

