    if (n == 1) {
        return cost[0];
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int stepOne = dp[i - 1] + cost[i - 1];
        int stepTwo = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(stepOne, stepTwo);
    }
    return dp[n];
}

