    if (cost == null) { 
        throw new IllegalArgumentException("cost array cannot be null"); 
    } 
    int n = cost.length; 
    if (n == 0) { 
        return 0; 
    } 
    if (n == 1) { 
        // Only one step exists; you can start at step 0 and reach the top by taking a single step, 
        // so no cost is required. 
        return 0; 
    } 
    int prevPrev = 0; // cost to reach step i-2 
    int prev = 0;     // cost to reach step i-1 
    for (int i = 2; i <= n; i++) { 
        int costFromPrev = prev + cost[i - 1]; 
        int costFromPrevPrev = prevPrev + cost[i - 2]; 
        int current = Math.min(costFromPrev, costFromPrevPrev); 
        prevPrev = prev; 
        prev = current; 
    } 
    return prev; 
}

