    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        // Can start from the step above the only step, so no cost.
        return 0;
    }
    int prev0 = cost[0];
    int prev1 = cost[1];
    for (int i = 2; i < n; i++) {
        int curr = cost[i] + Math.min(prev0, prev1);
        prev0 = prev1;
        prev1 = curr;
    }
    return Math.min(prev0, prev1);
}

