        if (c == '(') {
            balance++;
        } else if (c == ')') {
            balance--;
            if (balance < 0) {
                // we have an unmatched ')', need to insert a '(' before it
                insertions++;
                balance = 0;
            }
        } else {
            // invalid character, skip or could throw exception; here we skip
            continue;
        }
    }
    // any remaining unmatched '(' need matching ')'
    insertions += balance;
    return insertions;
}

