        minEnding = Math.min(val, minEnding + val);
        minSoFar = Math.min(minSoFar, minEnding);
    }
    return Math.max(Math.abs(maxSoFar), Math.abs(minSoFar));
}

public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxEnding = nums[0];
    int minEnding = nums[0];
    int maxSum = nums[0];
    int minSum = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        maxEnding = Math.max(val, maxEnding + val);
        minEnding = Math.min(val, minEnding + val);
        if (maxEnding > maxSum) {
            maxSum = maxEnding;
        }
        if (minEnding < minSum) {
            minSum = minEnding;
        }
    }
    int absMax = Math.abs(maxSum);
    int absMin = Math.abs(minSum);
    return Math.max(absMax, absMin);
}

