public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    int sqrt = (int)Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    int count = 0;
    for (int v : small) {
        count++;
        if (count == k) return v;
    }
    for (int i = large.size() - 1; i >= 0; i--) {
        count++;
        if (count == k) return large.get(i);
    }
    return -1;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) return -1;

    ArrayList<Integer> small = new ArrayList<>();
    ArrayList<Integer> large = new ArrayList<>();

    int sqrtN = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrtN; i++) {
        if (n % i == 0) {
            small.add(i);
            int counterpart = n / i;
            if (counterpart != i) { // avoid duplicate for perfect square
                large.add(counterpart);
            }
        }
    }

    int totalFactors = small.size() + large.size();
    if (k > totalFactors) return -1;

    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        int remaining = k - small.size();          // 1‑based index in large factors (ascending)
        int indexInLarge = large.size() - remaining; // reverse to get ascending order
        return large.get(indexInLarge);
    }
}

