            if (n % i == 0) {
                small.add(i);
                int j = n / i;
                if (j != i) {
                    big.add(j);
                }
            }
        }
        java.util.ArrayList<Integer> all = new java.util.ArrayList<>(small.size() + big.size());
        all.addAll(small);
        for (int idx = big.size() - 1; idx >= 0; idx--) {
            all.add(big.get(idx));
        }
        if (k - 1 >= all.size()) {
            return -1;
        }
        return all.get(k - 1);
    } catch (Exception e) {
        return -1;
    }
}

