public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> smallFactors = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> largeFactors = new java.util.ArrayList<>();
    int sqrtN = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrtN; i++) {
        if (n % i == 0) {
            smallFactors.add(i);
            int corresponding = n / i;
            if (corresponding != i) {
                largeFactors.add(corresponding);
            }
        }
    }
    int smallCount = smallFactors.size();
    if (k <= smallCount) {
        return smallFactors.get(k - 1);
    }
    int remaining = k - smallCount;
    int largeCount = largeFactors.size();
    if (remaining > largeCount) {
        return -1;
    }
    // largeFactors are in descending order; convert to ascending by indexing from end
    return largeFactors.get(largeCount - remaining);
}

public String makeGood(String s) {
    try {
        if (s == null) {
            return null;
        }
        StringBuilder stack = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            int len = stack.length();
            if (len > 0) {
                char top = stack.charAt(len - 1);
                if (Character.toLowerCase(c) == Character.toLowerCase(top)
                        && Character.isUpperCase(c) != Character.isUpperCase(top)) {
                    stack.deleteCharAt(len - 1);
                    continue;
                }
            }
            stack.append(c);
        }
        return stack.toString();
    } catch (Exception e) {
        // In case of unexpected runtime issues, return an empty string
        return "";
    }
}

public String makeGood(String s) {
    if (s == null) {
