    StringBuilder sb = new StringBuilder();
    for (char ch : s.toCharArray()) {
        int len = sb.length();
        if (len > 0) {
            char last = sb.charAt(len - 1);
            if (Character.toUpperCase(last) == Character.toUpperCase(ch) && last != ch) {
                sb.deleteCharAt(len - 1);
