            }
        }
        sb.append(ch);
    }
    return sb.toString();
}

public String makeGood(String s) {
    // Handle null or empty input gracefully
    if (s == null || s.isEmpty()) {
        return s == null ? "" : s;
    }

    StringBuilder stack = new StringBuilder();

    for (int i = 0; i < s.length(); i++) {
        char current = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char last = stack.charAt(len - 1);
            // Check if the last character and current character are the same letter
            // but of opposite cases: one is lowercase, the other is uppercase
            if (Character.toLowerCase(current) == Character.toLowerCase(last) && current != last) {
                // Remove the last character from the stack, effectively canceling them out
                stack.setLength(len - 1);
                continue;
            }
        }
        // No cancellation; push the current character onto the stack
        stack.append(current);
    }

    return stack.toString();
}

