            if (Math.abs(last - c) == 32) {
                sb.deleteCharAt(len - 1);
                continue;
            }
        }
        sb.append(c);
    }
    return sb.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int[] best = new int[1];
    dfs(s, 0, new java.util.HashSet<>(), 0, best);
    return best[0];
}

private void dfs(String s, int idx, java.util.Set<String> used, int count, int[] best) {
    if (idx == s.length()) {
        if (count > best[0]) {
            best[0] = count;
        }
        return;
    }
    for (int end = idx + 1; end <= s.length(); end++) {
        String sub = s.substring(idx, end);
        if (used.contains(sub)) {
            continue;
        }
        used.add(sub);
        dfs(s, end, used, count + 1, best);
        used.remove(sub);
    }
}

