private void dfs(int idx, String s, HashSet<String> used, int[] best) {
    if (idx == s.length()) {
        best[0] = Math.max(best[0], used.size());
        return;
    }
    for (int end = idx + 1; end <= s.length(); end++) {
        String sub = s.substring(idx, end);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(end, s, used, best);
            used.remove(sub);
        }
    }
}

public int maxUniqueSplit(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int n = s.length();
    if (n < 1 || n > 16) {
        throw new IllegalArgumentException("Input length must be between 1 and 16");
    }
    int max = 0;
    int totalMasks = 1 << (n - 1);
    for (int mask = 0; mask < totalMasks; mask++) {
        java.util.Set<String> seen = new java.util.HashSet<>();
        int segCount = 0;
        int start = 0;
        boolean valid = true;
        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) {
                String sub = s.substring(start, i + 1);
                if (!seen.add(sub)) {
                    valid = false;
                    break;
                }
                segCount++;
                start = i + 1;
            }
        }
        if (!valid) continue;
        String sub = s.substring(start);
        if (!seen.add(sub)) {
            continue;
        }
        segCount++;
        if (segCount > max) max = segCount;
    }
    return max;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    return dfs(0, new java.util.HashSet<>(), s);
}

private int dfs(int pos, java.util.Set<String> used, String s) {
    if (pos == s.length()) {
        return 0;
    }
    int maxParts = 0;
    for (int len = 1; pos + len <= s.length(); len++) {
        String part = s.substring(pos, pos + len);
        if (!used.contains(part)) {
            used.add(part);
            int count = dfs(pos + len, used, s);
            if (count + 1 > maxParts) {
                maxParts = count + 1;
            }
            used.remove(part);
        }
    }
    return maxParts;
}

