public String getSmallestString(int n, int k) {
    // Validate input: length must be positive and sum must be achievable
    if (n <= 0) {
        throw new IllegalArgumentException("Length n must be positive");
    }
    int minSum = n;            // all 'a'
    int maxSum = 26 * n;       // all 'z'
    if (k < minSum || k > maxSum) {
        throw new IllegalArgumentException("Sum k must be between n and 26*n");
    }

    char[] chars = new char[n];
    // Start with all 'a'
    java.util.Arrays.fill(chars, 'a');
    int delta = k - n; // how much we need to increase from the base 'a' sum

    // Distribute the needed increment from the end to keep lexicographically smallest
    for (int i = n - 1; i >= 0 && delta > 0; i--) {
        int inc = Math.min(25, delta); // max increment for a character (from 'a' to 'z')
        chars[i] = (char) ('a' + inc);
        delta -= inc;
    }

    return new String(chars);
}

