public static double calculateProbability(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Number of passengers must be a positive integer");
    }
    // If there's only one passenger, they obviously sit in their own seat.
    if (n == 1) {
        return 1.0;
    }
    // For any n > 1, the probability that the last passenger sits in their own seat is 0.5.
