}

private static void dfs(int depth, int last, int n, int[] A, boolean[] used, int[] result) {
    if (depth == n) {
        result[0]++;
        return;
    }
    for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue; // skip duplicates
        if (last != -1 && !isPerfectSquare(A[i] + last)) continue;
        used[i] = true;
        dfs(depth + 1, A[i], n, A, used, result);
        used[i] = false;
    }
}

