public static int largestRectangleArea(int[] heights) {
    // Validate input
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    int[] stack = new int[n + 1]; // stack of indices
    int top = 0; // stack size
    long maxArea = 0;

    for (int i = 0; i <= n; i++) {
        int curHeight = (i == n) ? 0 : Math.max(0, heights[i]); // sentinel height at the end
        while (top > 0) {
            int idx = stack[top - 1];
            int hTop = Math.max(0, heights[idx]);
            if (hTop <= curHeight) {
                break;
            }
            top--; // pop
            int width = (top == 0) ? i : i - stack[top - 1] - 1;
            long area = (long) hTop * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[top++] = i; // push current index
    }

    return (int) Math.min(maxArea, Integer.MAX_VALUE);
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum < m + n - 1; sum++) {
        if ((sum & 1) == 0) {
            int i = Math.min(sum, m - 1);
            int j = sum - i;
            while (i >= 0 && j < n) {
                result[idx++] = mat[i][j];
                i--;
                j++;
            }
        } else {
            int j = Math.min(sum, n - 1);
            int i = sum - j;
            while (j >= 0 && i < m) {
                result[idx++] = mat[i][j];
                i++;
                j--;
            }
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    // Handle null or empty matrix input
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    try {
        int m = mat.length;
        int n = mat[0].length;
        int[] result = new int[m * n];
        int row = 0, col = 0;
        boolean up = true;
        for (int idx = 0; idx < m * n; idx++) {
            result[idx] = mat[row][col];
            if (up) {
                if (col == n - 1) {          // hit the right boundary
                    row++;
                    up = false;
                } else if (row == 0) {       // hit the top boundary
                    col++;
                    up = false;
                } else {                     // move up-right
                    row--;
                    col++;
                }
            } else { // moving down-left
                if (row == m - 1) {          // hit the bottom boundary
                    col++;
                    up = true;
                } else if (col == 0) {       // hit the left boundary
                    row++;
                    up = true;
                } else {                     // move down-left
                    row++;
                    col--;
                }
            }
        }
        return result;
    } catch (Exception e) {
        // In case of any unexpected runtime errors, return an empty array
        return new int[0];
    }
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    // Verify that all rows have the same length
    for (int i = 1; i < m; ++i) {
        if (mat[i].length != n) {
            throw new IllegalArgumentException("Matrix rows must be of equal length");
        }
    }
    int[] res = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum <= m + n - 2; ++sum) {
        int start = Math.max(0, sum - (n - 1));
        int end   = Math.min(m - 1, sum);
        if ((sum & 1) == 0) { // even sum -> down to up (reverse)
            for (int i = end; i >= start; --i) {
                int j = sum - i;
                res[idx++] = mat[i][j];
            }
        } else { // odd sum -> up to down
            for (int i = start; i <= end; ++i) {
                int j = sum - i;
                res[idx++] = mat[i][j];
            }
        }
    }
    return res;
}

