    int[] res = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum < m + n - 1; sum++) {
        int startRow = Math.max(0, sum - (n - 1));
        int endRow = Math.min(m - 1, sum);
        if ((sum & 1) == 0) { // even sum, traverse from endRow to startRow
            for (int r = endRow; r >= startRow; r--) {
                int c = sum - r;
                res[idx++] = mat[r][c];
            }
        } else { // odd sum, traverse from startRow to endRow
            for (int r = startRow; r <= endRow; r++) {
                int c = sum - r;
                res[idx++] = mat[r][c];
            }
        }
    }
    return res;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // no higher permutation
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    // swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // reverse the suffix starting at i+1
    int left = i + 1;
    int right = digits.length - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1;
    }
}

