    }
    // Convert number to array of digits
    int len = Integer.toString(n).length();
    int[] digits = new int[len];
    int temp = n;
    for (int i = len - 1; i >= 0; i--) {
        digits[i] = temp % 10;
        temp /= 10;
    }

    // Find the pivot: the first digit from the right that is smaller than its next digit
    int pivot = len - 2;
    while (pivot >= 0 && digits[pivot] >= digits[pivot + 1]) {
        pivot--;
    }
    if (pivot < 0) {
        return -1; // No higher permutation exists
    }

    // Find the smallest digit greater than pivot digit to the right of pivot
    int successor = len - 1;
    while (digits[successor] <= digits[pivot]) {
        successor--;
    }

    // Swap pivot and successor
    int tempDigit = digits[pivot];
    digits[pivot] = digits[successor];
    digits[successor] = tempDigit;

    // Reverse the suffix to get the smallest possible order
    int left = pivot + 1, right = len - 1;
    while (left < right) {
        tempDigit = digits[left];
        digits[left] = digits[right];
        digits[right] = tempDigit;
        left++;
        right--;
    }

    // Build the resulting number and check for overflow
    long result = 0;
    for (int d : digits) {
        result = result * 10 + d;
        if (result > Integer.MAX_VALUE) {
            return -1; // Overflow, cannot return a valid int
        }
    }
    return (int) result;
}

