    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == prevChar) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            prevChar = c;
            currentLen = 1;
        }
    }
    if (currentLen > maxLen) {
        maxLen = currentLen;
    }
    return maxLen;
}

