public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>(n);
    if (n <= 0) {
        return result;
    }
    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);
        if (current <= n / 10) {
            current *= 10;
        } else {
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n < 1) {
        return result; // return empty list for non-positive input
    }
    try {
        for (int first = 1; first <= 9; first++) {
            dfs(first, n, result);
        }
    } catch (Exception e) {
        // In case of unexpected runtime errors, return an empty list
        result.clear();
    }
    return result;
}

private static void dfs(long current, int n, List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add((int) current);
    // Explore next level by multiplying by 10 and adding digits 0-9
    long nextBase = current * 10;
    for (int digit = 0; digit <= 9; digit++) {
        long next = nextBase + digit;
        if (next > n) {
            break; // no need to check larger digits
        }
        dfs(next, n, result);
    }
}

