public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input n must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    try {
        int[] dp = new int[n + 1];
        dp[0] = 0;
        for (int i = 1; i <= n; i++) {
            int min = Integer.MAX_VALUE;
            for (int j = 1; j * j <= i; j++) {
                int candidate = dp[i - j * j] + 1;
                if (candidate < min) {
                    min = candidate;
                }
            }
            dp[i] = min;
        }
        return dp[n];
    } catch (Exception e) {
        throw new RuntimeException("Error computing min perfect square sum", e);
    }
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    // dp[i] will hold the minimum number of perfect squares that sum to i
    int[] dp = new int[n + 1];
    // Use a large initial value for comparison; n is an upper bound for the answer
    final int INF = n + 1;
    for (int i = 1; i <= n; i++) {
        dp[i] = INF;
        for (int k = 1; k * k <= i; k++) {
            int square = k * k;
            int candidate = dp[i - square] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
