    }
    if (n == 0) {
        return 0;
    }

    int[] dp = new int[n + 1];
    final int INF = n + 1; // maximum possible number of squares is n (using 1^2)
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = INF;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    java.util.Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int j = 1;
        while (j * j <= i) {
            int square = j * j;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
            j++;
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    java.util.Arrays.fill(dp, Integer.MAX_VALUE / 2);
    dp[0] = 0;
    int maxRoot = (int) Math.sqrt(n);
    int[] squares = new int[maxRoot];
    for (int i = 1; i <= maxRoot; i++) {
        squares[i - 1] = i * i;
    }
    for (int i = 1; i <= n; i++) {
        for (int square : squares) {
            if (square > i) {
                break;
            }
            dp[i] = Math.min(dp[i], dp[i - square] + 1);
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    // Handle null input gracefully
    if (s == null) {
        return null;
    }
    // Split on space, keeping empty tokens to preserve original spacing
    String[] words = s.split(" ", -1);
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        // Reverse characters of the current word
        result.append(new StringBuilder(word).reverse());
        // Append a space after each word except the last one
        if (i < words.length - 1) {
            result.append(' ');
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    // Trim the string to handle leading/trailing spaces, then split by whitespace
    String trimmed = s.trim();
    if (trimmed.isEmpty()) {
        return "";
    }
    String[] words = trimmed.split("\\s+");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        // Reverse the word
        StringBuilder rev = new StringBuilder(word).reverse();
        result.append(rev);
        if (i < words.length - 1) {
            result.append(' ');
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c != ' ') {
            word.append(c);
        } else {
            result.append(word.reverse());
            word.setLength(0);
            result.append(c);
        }
    }
    if (word.length() > 0) {
        result.append(word.reverse());
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int n = s.length();
    int i = 0;
    while (i < n) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(c);
            i++;
        } else {
            int start = i;
            while (i < n && s.charAt(i) != ' ') {
                i++;
            }
            for (int j = i - 1; j >= start; j--) {
                result.append(s.charAt(j));
            }
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    if (s.isEmpty()) {
        return "";
    }
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        if (i > 0) {
            result.append(' ');
        }
        result.append(new StringBuilder(words[i]).reverse());
    }
    return result.toString();
}
